import { IssueResponse, VerifyResponse, CredentialPayload } from './types';

// Prefer Vite's import.meta.env (VITE_ prefix) which is substituted at build time.
// When served behind the same ingress host as the APIs the variables can be empty
// so the client uses relative paths like `/api/issue` which the nginx proxy routes.
// If Vite embedded vars are not present (e.g. image built without them), allow a
// runtime injection via /env.js that sets window.__ENV — generated by the container
// entrypoint in this repo. This lets Kubernetes env vars be exposed to the static SPA
// without rebuilding the image.
function readRuntime(key: string): string | undefined {
  try {
    // @ts-ignore
    if (typeof window !== 'undefined' && (window as any).__ENV) return (window as any).__ENV[key];
  } catch (e) {}
  return undefined;
}
// Helper: treat obvious template placeholders as "not set" (e.g. "${VITE_ISSUE_API}")
function isPlaceholder(v?: string) {
  if (!v) return true;
  return /^\$\{.*\}$/.test(v.trim());
}

const buildIssue = import.meta.env.VITE_ISSUE_API as string | undefined;
const buildVerify = import.meta.env.VITE_VERIFY_API as string | undefined;
const buildIssueKey = import.meta.env.VITE_ISSUE_API_KEY as string | undefined;
const buildVerifyKey = import.meta.env.VITE_VERIFY_API_KEY as string | undefined;

const ISSUE_BASE = !isPlaceholder(buildIssue) && buildIssue ? buildIssue : (readRuntime('VITE_ISSUE_API') || '');
const VERIFY_BASE = !isPlaceholder(buildVerify) && buildVerify ? buildVerify : (readRuntime('VITE_VERIFY_API') || '');
const ISSUE_KEY = !isPlaceholder(buildIssueKey) && buildIssueKey ? buildIssueKey : (readRuntime('VITE_ISSUE_API_KEY') || '');
const VERIFY_KEY = !isPlaceholder(buildVerifyKey) && buildVerifyKey ? buildVerifyKey : (readRuntime('VITE_VERIFY_API_KEY') || '');

export async function issueCredential(payload: CredentialPayload): Promise<IssueResponse> {
  const issueHeaders: any = { 'Content-Type': 'application/json' };
  if (ISSUE_KEY) issueHeaders['x-api-key'] = ISSUE_KEY;
  const res = await fetch(ISSUE_BASE + '/api/issue', {
    method: 'POST',
    headers: issueHeaders,
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(txt || `issue failed (${res.status})`);
  }
  return res.json();
}

export async function verifyCredential(payload: CredentialPayload): Promise<VerifyResponse> {
  const verifyHeaders: any = { 'Content-Type': 'application/json' };
  if (VERIFY_KEY) verifyHeaders['x-api-key'] = VERIFY_KEY;
  const res = await fetch(VERIFY_BASE + '/api/verify', {
    method: 'POST',
    headers: verifyHeaders,
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(txt || `verify failed (${res.status})`);
  }
  return res.json();
}
